```typescript
// string：文本
const prompt: string = "请帮我解释递归";
// number：整数和浮点数统一，64 位浮点
const temperature: number = 0.7;
const maxTokens: number = 4096;
const bigNum: number = 1_000_000; // 数字分隔符
// boolean：只有 true / false
const isStreaming: boolean = true;
// null：有意为之的「无值」
let lastResponse: string | null = null;
// undefined：声明了但没赋值
let apiKey: string | undefined;
// symbol：唯一且不可变，常用于对象属性的唯一键
const REQUEST_ID = Symbol("requestId");
// bigint：任意精度大整数（字面量后缀 n）
let totalTokens: bigint = 9007199254740993n;
totalTokens += 1_500_000n;
// bigint 不能与 number 直接混算
// const x = totalTokens + 1;   // 错误！
const x = totalTokens + 1n;      // 正确
```

```typescript
// 数组两种写法等价
let models: string[] = ["gpt-4o", "claude-3-5-sonnet"];
let scores: Array<number> = [0.92, 0.78, 0.85];
// 只读数组：防止意外修改（适合配置、常量列表）
const ALLOWED_MODELS: readonly string[] = ["gpt-4o", "claude-3-5-sonnet"];
// ALLOWED_MODELS.push("new-model"); // 错误！
// 元组（Tuple）：长度固定、每个位置类型确定
let point: [number, number] = [10, 20];
// 命名元组（TypeScript 4.0+）：每个位置有语义名称
type LLMResponse = [success: boolean, content: string, tokensUsed: number];
const result: LLMResponse = [true, "这是模型的回复", 256];
const [ok, text, tokens] = result; // 解构
console.log(`成功：${ok}，用了 ${tokens} tokens`);
// 可选元素和剩余元素
type RequestOptions = [prompt: string, temperature?: number, maxTokens?: number];
const req1: RequestOptions = ["解释量子计算"];
const req2: RequestOptions = ["解释量子计算", 0.7, 2048];
```

```typescript
// 数字枚举：成员从 0 自动递增，支持反向映射
enum RequestStatus {
  Pending,    // 0
  InProgress, // 1
  Completed,  // 2
  Failed      // 3
}
console.log(RequestStatus[0]); // "Pending"（反向映射）
// 字符串枚举：值可读，调试方便，推荐在 AI 应用中使用
enum MessageRole {
  System = "system",
  User = "user",
  Assistant = "assistant"
}
// 字符串枚举不支持反向映射
// const enum：编译时内联，零运行时开销
const enum TokenLimit {
  Small = 4096,
  Large = 128000
}
// 编译后 TokenLimit.Large 直接变为数字 128000
const limit: number = TokenLimit.Large;
```

```typescript
// any：完全绕过类型检查，危险
let rawData: any = fetchRawResponse();
rawData.someMethod(); // 不报错，但运行时可能崩溃
// unknown：安全的「未知类型」，使用前必须收窄
async function fetchFromAPI(url: string): Promise<unknown> {
  const res = await fetch(url);
  return res.json();
}
async function process(url: string): Promise<string> {
  const data: unknown = await fetchFromAPI(url);
  // 必须先检查，才能使用
  if (typeof data === "string") {
    return data.toUpperCase();
  }
  if (
    typeof data === "object" &&
    data !== null &&
    "content" in data &&
    typeof (data as { content: unknown }).content === "string"
  ) {
    return (data as { content: string }).content;
  }
  throw new Error("未知的响应格式");
}
```

原则：**处理外部数据时用 `unknown` 而不是 `any`；需要逐步迁移遗留代码时才用 `any`，并尽快替换掉它**。

```typescript
type LLMProvider = "openai" | "anthropic" | "google";
function getBaseURL(provider: LLMProvider): string {
  switch (provider) {
    case "openai":
      return "https://api.openai.com/v1";
    case "anthropic":
      return "https://api.anthropic.com/v1";
    case "google":
      return "https://generativelanguage.googleapis.com/v1beta";
    default:
      // 三个 case 都处理了，这里 provider 的类型就是 never
      // 如果以后 LLMProvider 新增了 "cohere"，TypeScript
      // 会在这里报错，提醒你补充对应的 case
      const _check: never = provider;
      throw new Error(`未处理的 provider：${_check}`);
  }
}
```

`never` 的这个用途本质上是：**让编译器替你检查「是否处理了所有分支」，而不是靠人工记忆**。

```typescript
// 枚举方式
enum Role {
  Admin = "admin",
  User = "user",
  Guest = "guest"
}
// 字符串字面量联合类型（更简洁，近年更流行）
type RoleUnion = "admin" | "user" | "guest";
```

什么时候用枚举？成员数量多（超过 5 个）、需要数字反向映射、需要在运行时遍历所有值（字符串枚举的枚举对象在运行时存在）。

什么时候用联合类型？成员数量少、值已经是有意义的字符串、不需要命名空间隔离——这种情况下联合类型更简洁，也不需要多一层 `import`。

TypeScript 的 `if/else` 不只是执行分支，还能通过**类型收窄（type narrowing）**让编译器在不同分支里获得更精确的类型信息。

```typescript
// 联合类型 + 属性判断收窄
type ModelOutput =
  | { type: "text"; content: string }
  | { type: "embedding"; vector: number[] }
  | { type: "error"; message: string; code: number };
function handleOutput(output: ModelOutput): void {
  if (output.type === "text") {
    // 这里 output 被收窄为 { type: "text"; content: string }
    console.log(output.content.trim());
  } else if (output.type === "embedding") {
    // 这里是 { type: "embedding"; vector: number[] }
    console.log(output.vector.length);
  } else {
    // 这里是 { type: "error"; message: string; code: number }
    console.error(`[${output.code}] ${output.message}`);
  }
}
// typeof 收窄：基本类型判断
function processInput(input: string | number): string {
  if (typeof input === "string") {
    return input.toUpperCase(); // input: string
  }
  return input.toFixed(2);     // input: number
}
```

`switch` 适合处理多个**离散值**的分支，配合 `never` 可以在编译期保证所有分支都被处理：

```typescript
type AIProvider = "openai" | "anthropic" | "google";
function assertNever(value: never): never {
  throw new Error(`未处理的值: ${JSON.stringify(value)}`);
}
function getApiEndpoint(provider: AIProvider): string {
  switch (provider) {
    case "openai":
      return "https://api.openai.com/v1";
    case "anthropic":
      return "https://api.anthropic.com/v1";
    case "google":
      return "https://generativelanguage.googleapis.com/v1beta";
    default:
      // 如果 AIProvider 新增了成员但 switch 没有处理，这里报编译错误
      return assertNever(provider);
  }
}
```

三元运算符适合简单的单行条件赋值，嵌套超过两层时可读性急剧下降，应改用 `if/else`。

```typescript
// for：精确控制索引，适合按批次划分
function processBatches<T>(data: T[], batchSize: number): T[][] {
  const batches: T[][] = [];
  for (let i = 0; i < data.length; i += batchSize) {
    batches.push(data.slice(i, i + batchSize));
  }
  return batches;
}
// for...of：遍历数组/可迭代对象，首选方式
const models = new Map<string, string[]>([
  ["gpt-4o", ["text", "vision"]],
  ["claude-3-5-sonnet", ["text", "vision", "long_context"]],
]);
for (const [model, caps] of models) {
  console.log(`${model}: ${caps.join(", ")}`);
}
// for...in：遍历对象的可枚举属性键
const hyperparams: Record<string, number> = {
  learningRate: 0.001,
  batchSize: 32,
};
for (const key in hyperparams) {
  if (Object.prototype.hasOwnProperty.call(hyperparams, key)) {
    console.log(`${key} = ${hyperparams[key]}`);
  }
}
// while：循环次数不确定时
let attempts = 0;
while (attempts < 3) {
  const ok = Math.random() > 0.7;
  if (ok) break;
  attempts++;
}
```

```typescript
// 函数声明（Function Declaration）：会被提升，可以在声明前调用
console.log(add(1, 2)); // 3，正常工作
function add(a: number, b: number): number {
  return a + b;
}
// 函数表达式（Function Expression）：不会提升，必须先定义再使用
const multiply = function(a: number, b: number): number {
  return a * b;
};
// 箭头函数（Arrow Function）：语法更简洁，this 词法绑定
const square = (x: number): number => x * x;
const makePoint = (x: number, y: number) => ({ x, y }); // 返回对象字面量要加括号
// this 绑定差异：箭头函数捕获外层 this
class Timer {
  private count = 0;
  startWithArrow(): void {
    setTimeout(() => {
      this.count++; // 正确：箭头函数词法绑定，this 是 Timer 实例
      console.log(this.count);
    }, 1000);
  }
  startWithRegular(): void {
    setTimeout(function() {
      // this.count++;  // 错误：普通函数 this 动态绑定，这里 this 不是 Timer 实例
    }, 1000);
  }
}
```

```typescript
// 可选参数（? 标记，自动变为 T | undefined，必须在必选参数之后）
function createPrompt(
  instruction: string,
  context?: string,
  examples?: string[]
): string {
  let prompt = instruction;
  if (context) prompt += `\n\n背景：${context}`;
  if (examples?.length) {
    prompt += `\n\n示例：\n${examples.map((e, i) => `${i + 1}. ${e}`).join("\n")}`;
  }
  return prompt;
}
// 默认参数（传 undefined 时也使用默认值）
function callAPI(
  prompt: string,
  model: string = "gpt-4o",
  temperature: number = 0.7
): object {
  return { prompt, model, temperature };
}
callAPI("你好");                     // model="gpt-4o", temperature=0.7
callAPI("你好", undefined, 0.0);     // model="gpt-4o"（undefined 触发默认值）
// 剩余参数（rest，必须是最后一个参数）
function mergeTexts(sep: string, ...texts: string[]): string {
  return texts.join(sep);
}
console.log(mergeTexts(" | ", "段落一", "段落二", "段落三"));
```

函数重载让同一个函数根据参数类型返回不同的类型，实现更精确的类型推断：

```typescript
// 重载签名（只有类型声明，没有实现）
function parseInput(input: string): string[];
function parseInput(input: number): number[];
function parseInput(input: string[]): string;
// 实现签名（必须兼容所有重载签名）
function parseInput(
  input: string | number | string[]
): string[] | number[] | string {
  if (typeof input === "string") {
    return input.split(",").map((s) => s.trim());
  } else if (typeof input === "number") {
    return Array.from({ length: input }, (_, i) => i);
  } else {
    return input.join(", ");
  }
}
const words = parseInput("apple, banana"); // 类型推断为 string[]
const nums = parseInput(5);               // 类型推断为 number[]
const joined = parseInput(["a", "b"]);    // 类型推断为 string
```

实现签名不对外暴露，只有重载签名才是调用者看到的类型接口。

```typescript
// 泛型函数：T 在调用时由实参类型推断
function identity<T>(value: T): T {
  return value;
}
const s = identity("hello"); // T 推断为 string
const n = identity(42);      // T 推断为 number
// 多泛型参数
function zip<T, U>(arr1: T[], arr2: U[]): [T, U][] {
  const len = Math.min(arr1.length, arr2.length);
  return Array.from({ length: len }, (_, i) => [arr1[i], arr2[i]]);
}
const pairs = zip([1, 2, 3], ["a", "b", "c"]);
// [[1, "a"], [2, "b"], [3, "c"]]
// 泛型约束：限制 T 必须有某些属性
interface HasLength { length: number; }
function longest<T extends HasLength>(a: T, b: T): T {
  return a.length >= b.length ? a : b;
}
longest("hello", "hi");       // "hello"
longest([1, 2, 3], [1, 2]);  // [1, 2, 3]
```
